import { env } from './env';

export interface PushMessage {
  token: string;
  notification: { title: string; body: string };
  data?: Record<string, string>;
}

/** In-memory outbox used when PUSH_TRANSPORT=memory (tests). */
export const pushOutbox: PushMessage[] = [];

/** Sends one push through the FCM HTTP v1 API. */
export async function sendPush(message: PushMessage): Promise<void> {
  if (env.pushTransport === 'memory') {
    pushOutbox.push(message);
    return;
  }
  const url = `${env.fcmEndpoint}/v1/projects/${env.fcmProject}/messages:send`;
  const res = await fetch(url, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      authorization: `Bearer ${env.fcmAccessToken}`,
    },
    body: JSON.stringify({ message }),
  });
  if (!res.ok) throw new Error(`fcm_send_failed status=${res.status}`);
}
import nodemailer from 'nodemailer';
import { env } from './env';

export interface Mail {
  to: string;
  subject: string;
  text: string;
}

/** In-memory outbox used when MAIL_TRANSPORT=memory (tests). */
export const mailOutbox: Mail[] = [];

let transporter: nodemailer.Transporter | undefined;

function getTransporter(): nodemailer.Transporter {
  if (!transporter) {
    transporter = nodemailer.createTransport({
      host: env.smtpHost,
      port: env.smtpPort,
      secure: false,
      ignoreTLS: true,
    });
  }
  return transporter;
}

export async function sendMail(mail: Mail): Promise<void> {
  if (env.mailTransport === 'memory') {
    mailOutbox.push(mail);
    return;
  }
  await getTransporter().sendMail({ from: env.mailFrom, to: mail.to, subject: mail.subject, text: mail.text });
}
